import {cities} from './cities.js';
import {createIndex,attachCitySearch,searchCities} from './city-search.js';
import {createCompassPools,chooseClues,shuffled,clueLayout,CompassRound} from './compass-model.js';
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
let pools,index=[],search,deck=[],game,round=0,compact=false;
function svgNode(tag,attrs={},text){const node=document.createElementNS(NS,tag);for(const [key,value] of Object.entries(attrs))node.setAttribute(key,value);if(text!==undefined)node.textContent=text;return node;}
function diagram(){
 if(!game)return;const svg=$('compass'),layout=clueLayout(game.clues,compact),{width,height,cx,cy,radius}=layout;
 svg.replaceChildren();svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.classList.toggle('compact',compact);
 svg.append(svgNode('title',{id:'diagram-title'},'Five bearings from the mystery city'),svgNode('desc',{id:'diagram-description'},`North is up. ${game.clues.map(c=>`${c.name}, ${c.country}: ${Math.round(c.bearing)} degrees clockwise from north`).join('. ')}. Arrow lengths do not indicate distance.`));
 const defs=svgNode('defs'),marker=svgNode('marker',{id:'arrow',viewBox:'0 0 10 10',refX:9,refY:5,markerWidth:7,markerHeight:7,orient:'auto-start-reverse'});marker.append(svgNode('path',{d:'M 0 0 L 10 5 L 0 10 z',fill:'#2853dd'}));defs.append(marker);svg.append(defs);
 svg.append(svgNode('circle',{cx,cy,r:radius,fill:'none',stroke:'#dce3ec','stroke-dasharray':'4 7'}),svgNode('path',{d:`M ${cx} ${cy-radius-24} V ${cy+radius+24} M ${cx-radius-24} ${cy} H ${cx+radius+24}`,stroke:'#e3e8ee',fill:'none'}),svgNode('text',{x:cx,y:34,'text-anchor':'middle',fill:'#77828d','font-family':'monospace','font-size':compact?25:19},'N ↑'));
 for(const clue of layout.entries){
  const labelWidth=compact?200:240,labelX=clue.side==='left'?14:width-14-labelWidth,edge=clue.side==='left'?labelX+labelWidth+8:labelX-8;
  svg.append(svgNode('path',{d:`M ${clue.tip.x} ${clue.tip.y} L ${edge} ${clue.labelY}`,stroke:'#b8c3cf','stroke-width':1.3,fill:'none'}),svgNode('line',{x1:clue.start.x,y1:clue.start.y,x2:clue.tip.x,y2:clue.tip.y,stroke:'#2853dd','stroke-width':3.5,'marker-end':'url(#arrow)'}));
  const box=svgNode('foreignObject',{x:labelX,y:clue.labelY-48,width:labelWidth,height:96});
  const label=document.createElementNS('http://www.w3.org/1999/xhtml','div');label.className=`compass-label ${clue.side}`;label.title=`${clue.name}, ${clue.country}`;
  const name=document.createElement('span');name.className='clue-name';name.textContent=clue.name;
  const country=document.createElement('span');country.className='clue-country';country.textContent=clue.country;label.append(name,country);box.append(label);svg.append(box);
 }
 svg.append(svgNode('circle',{cx,cy,r:68,fill:'#fff',stroke:'#25364a','stroke-width':2}),svgNode('text',{x:cx,y:cy+12,'text-anchor':'middle',fill:'#25364a','font-size':45,'font-family':'Arial'},game.done?(game.won?'✓':'·'):'?'),svgNode('text',{x:cx,y:cy+38,'text-anchor':'middle',fill:'#75808b','font-size':14,'font-family':'Arial'},game.done?'ANSWER BELOW':'MYSTERY CITY'));
}
function render(){const ready=!!game;$('guess').disabled=!ready||game.done;$('submit').disabled=!ready||game.done||!search?.selected;$('give-up').disabled=!ready||game.done;$('round').textContent=String(round).padStart(2,'0');$('attempts').textContent=game?.guesses.length??0;$('play').hidden=!!game?.done;$('result').hidden=!game?.done;
 const past=$('past-guesses');past.replaceChildren();past.hidden=!game?.guesses.length;for(const city of game?.guesses??[]){const li=document.createElement('li');li.textContent=city.name;li.title=city.country;if(city.id===game.answer.id)li.className='correct';past.append(li);}
}
function state(){return {round,poolSize:pools?.targets.length??0,guesses:game?.guesses.map(c=>c.name)??[],done:game?.done??false,clues:game?.clues.map(({id,name,country,bearing})=>({id,name,country,bearing}))??[],...(game?.done?{answer:game.answer.name}:{} )};}
function next(){if(game&&!game.done)throw Error('Finish the current round first.');const previous=game?.answer.id;if(!deck.length){deck=shuffled(pools.targets);if(deck.at(-1)?.id===previous)[deck[0],deck[deck.length-1]]=[deck.at(-1),deck[0]];}const answer=deck.pop();game=new CompassRound(answer,chooseClues(answer,pools.clues));round++;search.clear();$('feedback').textContent='Five bearings. As many guesses as you need.';diagram();render();return state();}
function finish(){search.close();$('answer').textContent=game.answer.name;$('result-detail').textContent=`${game.answer.country} · ${game.won?`Found in ${game.guesses.length} ${game.guesses.length===1?'guess':'guesses'}`:'Answer revealed'}`;diagram();render();$('next').focus();}
function guess(id){if(!game||game.done)throw Error('Wait for an active round.');const city=index.find(c=>c.id===id);if(!city)throw Error('Select a city from the database.');const accepted=game.guess(city);search.clear();if(game.done)finish();else{$('feedback').textContent=accepted?'Not quite. Try another city.':'Already tried that city.';render();$('guess').focus();}return state();}
function giveUp(){if(!game||game.done)throw Error('Wait for an active round.');game.giveUp();finish();return state();}
$('guess-form').addEventListener('submit',e=>{e.preventDefault();if(search?.selected)guess(search.selected.id);});$('give-up').addEventListener('click',giveUp);$('next').addEventListener('click',next);$('retry').addEventListener('click',init);
new ResizeObserver(entries=>{const small=entries[0].contentRect.width<600;if(compact!==small){compact=small;diagram();}}).observe($('compass-wrap'));
async function init(){try{$('retry').hidden=true;const response=await fetch('./city-database.json');if(!response.ok)throw Error('Data unavailable');const rows=await response.json();pools=createCompassPools(rows);index=createIndex(rows,cities);search=attachCitySearch(index,{input:$('guess'),list:$('city-options'),status:$('search-status'),onSelect:render,onChange:render});$('pool-label').textContent=`${pools.targets.length.toLocaleString('en')} CITIES · FIVE BEARINGS`;$('load-status').hidden=true;next();}catch{$('load-status').firstChild.textContent='Unable to load cities. ';$('load-status').hidden=false;$('retry').hidden=false;}}
init();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const empty={type:'object',properties:{},additionalProperties:false};const tools=[{name:'read_city_compass',description:'Read the five city bearings and round state. The answer is hidden until the round ends.',inputSchema:empty,annotations:{readOnlyHint:true},execute:state},{name:'search_compass_cities',description:'Search for a city ID to guess.',inputSchema:{type:'object',properties:{query:{type:'string',minLength:2}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(typeof input?.query!=='string'||input.query.trim().length<2)throw Error('Enter at least two characters.');return searchCities(index,input.query).map(({id,name,country})=>({id,name,country}));}},{name:'guess_compass_city',description:'Guess the city at the centre by GeoNames ID.',inputSchema:{type:'object',properties:{cityId:{type:'integer'}},required:['cityId'],additionalProperties:false},execute:input=>guess(input?.cityId)},{name:'give_up_compass',description:'Reveal the mystery city.',inputSchema:empty,execute:giveUp},{name:'next_compass_city',description:'Start a new randomized round after finishing the previous one.',inputSchema:empty,execute:()=>{if(!pools)throw Error('Wait for cities to load.');return next();}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool({...tool,annotations:{readOnlyHint:false,...tool.annotations}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
